export function createStorageChoice({choose}){
  const dialog=document.createElement('dialog');dialog.className='storage-dialog';dialog.setAttribute('aria-labelledby','storage-title');document.body.append(dialog);
  let scope=null;
  const names={personality:'Osobnost a temperament',intimacy:'Intimní profil'};
  function open(part){scope=part;dialog.innerHTML=`<span class="eyebrow">TEST JE DOKONČENÝ · ${names[part]}</span><h2 id="storage-title">Kde chceš mít výsledek?</h2><p>Rozhoduješ jen o tomto testu. U druhého testu si vybereš zvlášť.</p><div class="storage-options"><button class="storage-option" data-storage="account"><strong>Na můj účet</strong><span>Výsledky budou kdykoliv dostupné z účtu, i na jiném zařízení. Získáš možnost vytvořit kód pro párové porovnávání. Pokud nemáš účet, vytvoříš ho v dalším kroku.</span></button><button class="storage-option" data-storage="device"><strong>Do tohoto telefonu / prohlížeče</strong><span>Bez účtu. Tento test se obnoví i po zavření a novém otevření webu. Výsledek tu může otevřít i další člověk používající tento prohlížeč.</span></button><button class="storage-option" data-storage="session"><strong>Jen pro tuto relaci</strong><span>Bez dlouhodobého uložení. Výsledek zůstane při obnovení stránky v této kartě, na server se neuloží.</span></button></div><p class="fine-print">Uložení na účet není automatické sdílení. Kód i jeho obsah vybíráš zvlášť. Relaci může prohlížeč obnovit při obnovení zavřených karet. Pro jisté odstranění použij smazání profilu.</p><p class="storage-error" role="alert"></p><button class="text-button" data-storage="later">Rozhodnout později</button>`;dialog.returnValue='';dialog.showModal();}
  dialog.addEventListener('click',event=>{const button=event.target.closest('[data-storage]');if(!button)return;if(button.dataset.storage==='later'){dialog.close();return;}const mode=button.dataset.storage;const result=choose(scope,mode);if(result===false){dialog.querySelector('.storage-error').textContent='Uložení se nepodařilo. Odpovědi zůstaly v otevřené stránce. Zkontroluj stav ukládání nahoře nebo zvol účet.';return;}dialog.close();});
  return {open};
}
